local reps = {['gregtech:gt.depletedRodUranium4'] = 'gregtech:gt.rodUranium4', ['gregtech:gt.depletedRodMOX4'] = 'gregtech:gt.rodUranium4', ['gregtech:gt.depletedRodThorium4'] = 'gregtech:gt.rodThorium4', ['gregtech:gt.depletedRodThorium'] = 'gregtech:gt.rodThorium', ['gregtech:gt.depletedRodGlowstone'] = 'gregtech:gt.rodGlowstone'} local trans = require('component').transposer local function findItemSlot(side, name) local size = trans.getInventorySize(side) for k=1,size do local item = trans.getStackInSlot(side, k) if item and item.name == name then return k end end end local reactor, chest for side=0,5 do local name = trans.getInventoryName(side) if name == 'blockGenerator' or name == 'blockReactorChambed' then reactor = side elseif name == 'tile.chest' then chest = side end end if reactor and chest then while 1 do os.sleep(1) for depName,repName in pairs(reps) do local depFuel = findItemSlot(reactor, depName) if depFuel then local repFuel = findItemSlot(chest, repName) if repFuel then trans.swap(reactor, chest, depFuel, repFuel) print(depName) end end end end else print('No reactor or chest') end